    async def get_run_steps(self, run_id: str, *, limit: Optional[int] = None, cursor: Optional[str] = None, request_options: Optional[RequestOptions] = None) -> _m.GetRunStepsResponse:
        """List steps for a run

        Returns the ordered list of steps executed during a run, with per-step metrics including
        tokens, cost, and tool calls. Model calls a run makes outside any step — the effort
        classifier, the planner, the evaluator — are reported once in `outside_steps`, so the steps'
        `cost_usd` plus `outside_steps.cost_usd` equals the run's `total_cost_usd` (both priced the
        way the run is billed).

        `GET /api/v1/runs/{runId}/steps`

        Required scopes: `runs:read`.
        """
        return _cast("_m.GetRunStepsResponse", await self._client._request(
            "GET",
            f"/api/v1/runs/{_segment(run_id)}/steps",
            query=[("limit", limit), ("cursor", cursor)],
            response=_Response(type=_m.GetRunStepsResponse),
            request_options=request_options,
        ))

    async def get_run_steps_all(self, run_id: str, *, limit: Optional[int] = None, cursor: Optional[str] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[_m.RunStep]:
        """Every item `get_run_steps` returns, following the `cursor` cursor until the server reports
        no further pages. Starts at `cursor` when one is given.
        """
        guard = _CursorGuard()
        while True:
            page = await self.get_run_steps(run_id, limit=limit, cursor=cursor, request_options=request_options)
            items = page.steps
            for item in items:
                yield item

            cursor = guard.advance(page.cursor, page.has_more, not items)
            if cursor is None:
                return

    async def list(self, *, client_request_id: Optional[str] = None, purpose: Optional[str] = None, agent_id: Optional[str] = None, session_id: Optional[str] = None, status: Optional[str] = None, limit: Optional[int] = None, cursor: Optional[str] = None, order: Optional[_m.ListRunsOrder] = None, request_options: Optional[RequestOptions] = None) -> _m.ListRunsResponse:
        """List all runs for tenant

        Ordered NEWEST FIRST, and that is a guarantee, not an accident of storage: page one is the
        most recent runs. Do not page toward the end to find recent activity — a client that walks
        `has_more` looking for the newest page now walks away from it. This was previously true only
        of the handler, so clients hedged by paging or by re-sorting, and one shipped a twelve-hop
        walk that reversed meaning the day the order changed. Note the sibling
        `/api/v1/teams/{teamId}/runs` is deliberately the other way round — oldest first — because a
        team transcript reads forward.

        `GET /api/v1/runs`

        Required scopes: `runs:read`.
        """
        return _cast("_m.ListRunsResponse", await self._client._request(
            "GET",
            "/api/v1/runs",
            query=[("client_request_id", client_request_id), ("purpose", purpose), ("agent_id", agent_id), ("session_id", session_id), ("status", status), ("limit", limit), ("cursor", cursor), ("order", order)],
            response=_Response(type=_m.ListRunsResponse),
            request_options=request_options,
        ))

    async def list_all(self, *, client_request_id: Optional[str] = None, purpose: Optional[str] = None, agent_id: Optional[str] = None, session_id: Optional[str] = None, status: Optional[str] = None, limit: Optional[int] = None, cursor: Optional[str] = None, order: Optional[_m.ListRunsOrder] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[_m.Run]:
        """Every item `list` returns, following the `cursor` cursor until the server reports no further
        pages. Starts at `cursor` when one is given.
        """
        guard = _CursorGuard()
        while True:
            page = await self.list(client_request_id=client_request_id, purpose=purpose, agent_id=agent_id, session_id=session_id, status=status, limit=limit, cursor=cursor, order=order, request_options=request_options)
            items = page.items
            for item in items:
                yield item

            cursor = guard.advance(page.cursor, page.has_more, not items)
            if cursor is None:
                return

